fn largest_divisor(n: i8) -> i8 {
    assert!(n > 1);

    // The largest proper divisor of n is n / p where p is the smallest divisor > 1.
    // We search for the smallest divisor in [2, sqrt(n)].
    let n_i16 = n as i16;
    let mut d: i16 = 2;

    while d * d <= n_i16 {
        if n_i16 % d == 0 {
            return (n_i16 / d) as i8;
        }
        d += 1;
    }

    // If no divisor found, n is prime; largest proper divisor is 1.
    1
}